<template>
 <section class="gm-traffic-detail">
  <header class="traffic-detail-heading"><div><span class="traffic-eyebrow">АНАЛИЗ ТРАФИКА</span><h1>{{ currentId?'Сессия #'+currentId:'Исследуйте трафик' }}</h1><p>{{ currentId?'Запросы и ответы в порядке захвата. Выделите значение, чтобы декодировать его.':'Выберите сессию в списке, чтобы увидеть запросы, ответы и совпадения с шаблонами.' }}</p></div><span v-if="currentId" class="traffic-block-count">{{ packets.length }} блоков на странице</span></header>
  <template v-if="currentId">
   <section class="packet-view-toolbar" aria-label="Представление пакетов">
    <div class="packet-view-field"><label for="packet-representation">Содержимое</label><select id="packet-representation" class="custom-select custom-select-sm" v-model="representation" @change="reset"><option value="">Все блоки</option><option value="raw">Исходные байты</option><option value="decoded">Разобранные сообщения</option></select></div>
    <div class="packet-view-field"><label for="packet-direction">Направление на странице</label><select id="packet-direction" class="custom-select custom-select-sm" v-model="direction"><option value="">Запросы и ответы</option><option value="incoming">Только запросы</option><option value="outgoing">Только ответы</option></select></div>
    <div class="packet-view-field"><label>Отображение</label><div class="packet-display" role="group" aria-label="Отображение содержимого"><button type="button" :class="{active:!$store.state.hexdumpMode}" :aria-pressed="String(!$store.state.hexdumpMode)" @click="setHex(false)">Текст</button><button type="button" :class="{active:$store.state.hexdumpMode}" :aria-pressed="String($store.state.hexdumpMode)" @click="setHex(true)">HEX</button></div></div>
   </section>
   <div v-if="representation||direction" class="packet-active-filters" aria-label="Активные фильтры блоков"><span>Показаны:</span><button v-if="representation" @click="representation='';reset()" :aria-label="'Убрать фильтр содержимого'">{{ representation==='raw'?'Исходные байты':'Разобранные сообщения' }} <i class="fas fa-times" aria-hidden="true"/></button><button v-if="direction" @click="direction=''" aria-label="Убрать фильтр направления">{{ direction==='incoming'?'Запросы':'Ответы' }} <i class="fas fa-times" aria-hidden="true"/></button><button class="packet-reset-view" @click="clearView">Сбросить</button></div>
   <div class="packet-legend"><span><i class="legend-in"/>Запрос к сервису</span><span><i class="legend-out"/>Ответ сервиса</span><span class="packet-live-note">{{ $store.state.pause?'Обновление приостановлено':'Открытые соединения обновляются автоматически' }}</span></div>
   <div v-if="error" class="packet-error" role="alert">{{ error }} <button class="btn btn-sm btn-outline-secondary" @click="load">Повторить</button></div>
   <div v-if="loading&&!packets.length" class="packet-empty" role="status"><i class="fas fa-circle-notch fa-spin" aria-hidden="true"/><h2>Загружаем содержимое</h2><p>Получаем выбранную страницу сессии.</p></div>
   <div v-else-if="!packetsWithOffsets.length" class="packet-empty"><i class="fas fa-filter" aria-hidden="true"/><h2>{{ packets.length?'Нет блоков этого направления':'Нет доступных блоков' }}</h2><p>{{ packets.length?'Измените направление или перейдите на следующую страницу.':'Попробуйте другое представление. Содержимое также могло быть удалено по сроку хранения.' }}</p><button v-if="representation||direction" class="btn btn-sm btn-outline-primary" @click="clearView">Показать все блоки</button></div>
   <div class="packet-list"><Packet v-for="packetWithOffset in packetsWithOffsets" :key="packetWithOffset.packet.id" :packet="packetWithOffset.packet" :offset="packetWithOffset.offset" @decode="openDecoder"/></div>
   <footer class="packet-pagination"><button class="btn btn-sm btn-outline-secondary" :disabled="!history.length||loading" @click="previousPage"><i class="fas fa-arrow-left" aria-hidden="true"/> Предыдущие блоки</button><span>Страница {{ history.length+1 }}</span><button class="btn btn-sm btn-outline-secondary" :disabled="!hasMore||loading" @click="nextPage">Следующие блоки <i class="fas fa-arrow-right" aria-hidden="true"/></button></footer>
  </template>
  <div v-else class="traffic-welcome"><div class="welcome-icon"><i class="fas fa-stream" aria-hidden="true"/></div><h2>От сессии к деталям</h2><p>Сузьте список по сервису или шаблону.<br>Откройте сессию и исследуйте каждый блок.</p><div class="welcome-steps"><div><span>01</span><strong>Выберите сессию</strong><small>Фильтры и избранное — слева</small></div><div><span>02</span><strong>Разберите содержимое</strong><small>Текст, HEX и декодирование</small></div><div><span>03</span><strong>Найдите важное</strong><small>Совпадения подсвечены в трафике</small></div></div></div>
  <TrafficDecoder ref="decoder"/>
 </section>
</template>
<script>
import Packet from '../components/Packet';
import TrafficDecoder from '@/components/TrafficDecoder.vue';
export default {
 name:'ContentStream',components:{Packet,TrafficDecoder},props:['servicePort','streamId'],
 data:()=>({packets:[],cursor:null,history:[],loading:false,hasMore:false,generation:0,error:'',representation:'',direction:''}),
 computed:{currentId(){return this.$route.params.streamId},packetsWithOffsets(){return this.packets.map((packet,i)=>({packet,offset:i?packet.timestamp-this.packets[i-1].timestamp:null})).filter(({packet})=>!this.direction||packet.incoming===(this.direction==='incoming'))}},
 mounted(){this.reset()},beforeDestroy(){this.generation++},watch:{'$route.params.streamId':'reset'},
 methods:{
  openDecoder(value){this.$refs.decoder.open(value)},setHex(value){if(this.$store.state.hexdumpMode!==value)this.$store.commit('toggleHexdumpMode')},
  clearView(){this.representation='';this.direction='';this.reset()},
  reset(){this.packets=[];this.cursor=null;this.history=[];this.error='';this.load()},
  async load(){const generation=++this.generation;if(!this.currentId){this.loading=false;return}this.loading=true;const pageSize=Math.max(1,Math.min(50,Number(this.$store.state.pageSize)||25));try{const {data,headers}=await this.$http.post(`/packet/${this.currentId}`,{startingFrom:this.cursor,pageSize,representation:this.representation});if(generation!==this.generation)return;this.packets=data;this.hasMore=headers['x-has-more']==='true';this.error=''}catch(e){if(generation===this.generation)this.error='Не удалось загрузить содержимое сессии.'}finally{if(generation===this.generation)this.loading=false}},
  refreshLive(){if(!this.loading&&!this.hasMore&&!this.$store.state.pause)return this.load()},
  nextPage(){if(!this.packets.length)return;this.history.push(this.cursor);if(this.history.length>1000)this.history.shift();this.cursor=this.packets[this.packets.length-1].id;this.load()},
  previousPage(){this.cursor=this.history.pop()??null;this.load()},
 },
};
</script>
<style scoped>
.gm-traffic-detail{min-width:0}.traffic-detail-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:8px 0 20px}.traffic-eyebrow{color:var(--gm-accent);font-size:.75rem;letter-spacing:.14em;font-weight:700}.traffic-detail-heading h1{font-size:1.55rem;font-weight:700;letter-spacing:-.04em;margin:7px 0 8px}.traffic-detail-heading p{font-size:.78rem;line-height:1.6;color:var(--gm-muted);margin:0;max-width:600px}.traffic-block-count{font-size:.75rem;color:var(--gm-muted);white-space:nowrap}.packet-view-toolbar{display:flex;gap:16px;align-items:end;flex-wrap:wrap;background:var(--gm-panel);border:1px solid var(--gm-border);border-radius:var(--gm-radius);padding:14px 16px}.packet-view-field{flex:1;min-width:165px}.packet-view-field:last-child{flex:0 0 auto;min-width:140px}.packet-view-field label{display:block;font-size:.75rem;font-weight:600;color:var(--gm-muted);margin-bottom:7px}.packet-display{display:flex;border:1px solid var(--gm-border);border-radius:6px;overflow:hidden;padding:3px;background:var(--gm-bg)}.packet-display button{border:0;border-radius:4px;padding:5px 14px;background:transparent;color:var(--gm-muted);font-size:.75rem;cursor:pointer}.packet-display button.active{background:var(--gm-accent-soft);color:var(--gm-accent);font-weight:600}.packet-active-filters{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:10px;font-size:.75rem;color:var(--gm-muted)}.packet-active-filters button{border:1px solid var(--gm-accent);background:var(--gm-accent-soft);color:var(--gm-accent);padding:4px 8px;border-radius:5px;font-size:.75rem;cursor:pointer}.packet-active-filters button i{margin-left:5px;font-size:.75rem}.packet-active-filters .packet-reset-view{border:0;background:none}.packet-legend{display:flex;flex-wrap:wrap;gap:16px;padding:15px 2px;color:var(--gm-muted);font-size:.75rem}.packet-legend>span{display:flex;align-items:center;gap:6px}.packet-legend i{display:inline-block;width:6px;height:6px;border-radius:50%}.legend-in{background:var(--gm-accent)}.legend-out{background:var(--gm-warning)}.packet-live-note{margin-left:auto}.packet-list{display:grid;gap:14px}.packet-pagination{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:20px 0 12px;flex-wrap:wrap}.packet-pagination>span{font-size:.75rem;color:var(--gm-muted)}.packet-error{color:var(--gm-danger);padding:16px}.packet-empty{padding:40px 20px;text-align:center;border:1px dashed var(--gm-border);border-radius:var(--gm-radius);color:var(--gm-muted)}.packet-empty>i{font-size:1.5rem;margin-bottom:15px}.packet-empty h2{font-size:1rem;color:var(--gm-text)}.packet-empty p{font-size:.8rem}.traffic-welcome{border:1px solid var(--gm-border);border-radius:var(--gm-radius);background:var(--gm-panel);min-height:470px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px 24px;text-align:center}.welcome-icon{background:var(--gm-accent-soft);color:var(--gm-accent);width:64px;height:64px;display:grid;place-items:center;border:1px solid var(--gm-border);border-radius:16px;font-size:1.5rem;margin-bottom:24px}.traffic-welcome h2{font-size:1.2rem;font-weight:600;letter-spacing:-.025em}.traffic-welcome>p{font-size:.8rem;line-height:1.8;color:var(--gm-muted)}.welcome-steps{display:flex;gap:30px;margin-top:30px;flex-wrap:wrap;justify-content:center}.welcome-steps>div{display:flex;flex-direction:column;gap:5px;align-items:center}.welcome-steps span{font-family:var(--gm-mono);font-size:.75rem;color:var(--gm-accent);margin-bottom:6px}.welcome-steps strong{font-size:.75rem;font-weight:600}.welcome-steps small{font-size:.75rem;color:var(--gm-muted)}@media(max-width:767px){.traffic-detail-heading{align-items:start}.traffic-block-count{display:none}.traffic-welcome{min-height:350px}.packet-view-field{min-width:140px}.packet-live-note{margin-left:0}.packet-view-toolbar{gap:12px}}
</style>
